<template><section class="sf-feedback" :class="'sf-feedback--'+tone" :role="tone==='error'?'alert':'status'"><sf-icon :name="tone==='success'?'check':tone==='empty'?'calendar':'info'" :size="28"/><h3>{{ title }}</h3><p v-if="description">{{ description }}</p><slot/><button v-if="action" type="button" class="sf-feedback__action" @click="$emit('action')">{{ action }}</button></section></template>
<script>import SfIcon from './SfIcon';export default {name:'SfFeedback',components:{SfIcon},props:{title:{type:String,required:true},description:String,action:String,tone:{type:String,default:'empty',validator:v=>['empty','error','success','info'].includes(v)}}}</script>
